def rearange_string(s):
  count = Counter(s)
  max_count = max(count.values())
  max_char = count.most_common(1)[0][0]
  remaining_chars = {char: count[char] - max_count for char in count if char != max_char}
  if len(remaining_chars) > 1:
    return ''
  else:
    return max_char * max_count + ''.join(sorted(remaining_chars.keys(), key=lambda x: count[x]))

