  for row in matrix:
    if sum(row) != sum_first_row:
      return False

  # Check if all columns have the same sum
  for col_index in range(len(matrix)):
    column_sum = sum(matrix[row_index][col_index] for row_index in range(len(matrix)))
    if column_sum != sum_first_row:
      return False

  # Check if both diagonals have the same sum
  diagonal_1_sum = sum(matrix[i][i] for i in range(len(matrix)))
  diagonal_2_sum = sum(matrix[i][len(matrix)-1-i] for i in range(len(matrix)))
