        return True
    # If no elements left and sum is not zero, then it's not possible to form the sum
    if n == 0: 
        return False
    # If last element is greater than sum, then ignore it
    if arr[n-1] > sum: 
        return is_subset_sum(arr, n-1, sum) 
    # Case 1: Include the last element in the subset
    include = is_subset_sum(arr, n-1, sum - arr[n-1]) 
    # Case 2: Exclude the last element from the subset
    exclude = is_subset_sum(arr, n-1, sum) 
    # Return true if either case returns true
    return include or exclude

